// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount && tx.origin != address(this));
        uint256 before_caller;
        try c.balances(address(this)) returns (uint256 __r) { before_caller = __r; } catch { return; }
        uint256 before_origin;
        try c.balances(tx.origin) returns (uint256 __r) { before_origin = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 after_caller;
        try c.balances(address(this)) returns (uint256 __r) { after_caller = __r; } catch { return; }
        uint256 after_origin;
        try c.balances(tx.origin) returns (uint256 __r) { after_origin = __r; } catch { return; }
        assertTrue(after_caller == before_caller + amount && after_origin == before_origin);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
